<?php require_once 'koneksi.php'; require_once 'session.php'; require_once 'helper.php'; if(!in_array($_SESSION['role']??'',['admin','petugas'],true)) exit('403'); $a=$_GET['aksi']??''; if($a==='tambah'){ $n=trim($_POST['namaasal']??''); mysqli_query($koneksi,"INSERT INTO asal(namaasal) VALUES('".bersih($n)."')"); } elseif($a==='edit'){ $id=(int)$_POST['idasal']; mysqli_query($koneksi,"UPDATE asal SET namaasal='".bersih($_POST['namaasal'])."' WHERE idasal=$id"); } elseif($a==='hapus'){ $id=(int)$_GET['id']; mysqli_query($koneksi,"DELETE FROM asal WHERE idasal=$id"); } redirect('../index.php?halaman=asal');